def _tables(r):
  d=(r.get('response',{}) or {}).get('data') or (r.get('response',{}) or {}).get('data_preview') or {}
  return d.get('tables') or []

def summarize(payload):
  out=[]
  for r in payload.get('results',[]) or []:
    for t in _tables(r):
      out.append((t.get('full_name'),len(t.get('columns') or []),len(t.get('foreign_keys') or [])))
  return out

def fk_edges(payload):
  out=[]
  for r in payload.get('results',[]) or []:
    for t in _tables(r):
      src=t.get('full_name')
      for fk in (t.get('foreign_keys') or []):
        out.append({'from_table':src,'from_column':fk.get('source_column'),'to_table':str(fk.get('target_schema'))+'.'+str(fk.get('target_table')),'to_column':fk.get('target_column'),'constraint_name':fk.get('constraint_name')})
  return out
